import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Apps","description":"","frontmatter":{},"headers":[],"relativePath":"guide/apps.md","filePath":"guide/apps.md"}'),p={name:"guide/apps.md"};function n(l,a,o,r,d,h){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="apps" tabindex="-1">Apps <a class="header-anchor" href="#apps" aria-label="Permalink to &quot;Apps&quot;">​</a></h1><p>The App Store installs Docker Compose applications and exposes their declared ports through the gateway proxy. Some apps also include an agent or host-script bridge.</p><h2 id="inspect-and-install" tabindex="-1">Inspect and install <a class="header-anchor" href="#inspect-and-install" aria-label="Permalink to &quot;Inspect and install&quot;">​</a></h2><p>You need a working Docker/Compose environment and an admin API key. Start by listing installed apps:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Install from a registry name, a GitHub URL, or an existing local app directory. For example, for a local app you have reviewed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span></span></code></pre></div><p>The source directory must contain the gateway app manifest and its required files. <code>--wait</code> polls the installation job and streams logs. Without it, the command returns an accepted <code>jobId</code>; inspect completion with <code>claude-gateway api GET /v1/apps/jobs/JOB_ID</code>.</p><p>App URLs follow <code>/app/:name/:portName/*</code>. Verify the job&#39;s final result, then load the app and exercise a small action before calling the installation successful.</p><h2 id="operate-an-app" tabindex="-1">Operate an app <a class="header-anchor" href="#operate-an-app" aria-label="Permalink to &quot;Operate an app&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> APP_NAME</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Use <code>--env-file</code> when an install needs secrets. An uninstall removes containers and installed files while retaining backups; it asks for confirmation. Review <code>gateway.appBackup</code>, <code>gateway.appRestore</code>, and <code>gateway.appHousekeeping</code> when planning storage and recovery.</p><p>See the <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#app-store" target="_blank" rel="noreferrer">App Store reference</a> and <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/CLI.md#app-store-docker-compose-apps" target="_blank" rel="noreferrer">CLI install semantics</a> for manifests, sources, and backup operations. Container admission and migration behavior specific to orchestration belongs to the <a href="./../preview/orchestration.html">unreleased preview</a>.</p>`,13)])])}const g=e(p,[["render",n]]);export{k as __pageData,g as default};
